    {
      "keystrokes": "cat > src/main.ts << 'EOF'
import { Filesystem, Directory } from '@capacitor/filesystem';

const statusEl = document.getElementById('download-status') as HTMLElement;
const sizeEl = document.getElementById('file-size') as HTMLElement;
const shaEl = document.getElementById('file-sha256') as HTMLElement;
const button = document.getElementById('download-pdf') as HTMLButtonElement;

function setStatus(text: string): void {
  statusEl.textContent = text;
}

function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, i + chunkSize);
    binary += String.fromCharCode.apply(null, Array.from(chunk));
  }
  return btoa(binary);
}

function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

function bufferToHex(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let hex = '';
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, '0');
  }
  return hex;
}

async function downloadAndPersist(): Promise<void> {
  setStatus('downloading');
  sizeEl.textContent = '';
  shaEl.textContent = '';

  try {
    const response = await fetch('/sample.pdf');
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    const arrayBuffer = await response.arrayBuffer();
    const base64 = arrayBufferToBase64(arrayBuffer);

    await Filesystem.writeFile({
      path: 'sample.pdf',
      data: base64,
      directory: Directory.Documents,
      recursive: true,
    });

    const readResult = await Filesystem.readFile({
      path: 'sample.pdf',
      directory: Directory.Documents,
    });

    let dataString: string;
    if (typeof readResult.data === 'string') {
      dataString = readResult.data;
    } else if (readResult.data instanceof Blob) {
      const buf = await readResult.data.arrayBuffer();
      dataString = arrayBufferToBase64(buf);
    } else {
      throw new Error('Unexpected data type from Filesystem.readFile');
    }

    const stat = await Filesystem.stat({
      path: 'sample.pdf',
      directory: Directory.Documents,
    });

    const sizeFromStat = typeof stat.size === 'number' ? stat.size : Number(stat.size);
    const buffer = base64ToArrayBuffer(dataString);
    const computedSize = buffer.byteLength;
    const finalSize = Number.isFinite(sizeFromStat) && sizeFromStat > 0 ? sizeFromStat : computedSize;

    const digest = await crypto.subtle.digest('SHA-256', buffer);
    const sha256 = bufferToHex(digest);

    sizeEl.textContent = String(finalSize);
    shaEl.textContent = sha256;
    setStatus('saved');
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    setStatus(`error: ${message}`);
  }
}

button.addEventListener('click', () => {
  void downloadAndPersist();
});
EOF
